import{_ as r,C as o,o as p,c as l,j as t,a as n,E as s,a5 as i}from"./chunks/framework.DNkHA0lr.js";const f=JSON.parse('{"title":"如何：在任何技能上成为前1%","description":"","frontmatter":{"title":"如何：在任何技能上成为前1%","originalTitle":"How To: Become The Top 1% In Any Skill","date":"2022-01-29","originalUrl":"https://thedankoe.com/letters/how-to-become-the-top-1-percent-in-any-skill/","minutes":8,"sourceHash":"67d20b49c2647be3b687106397dbd03502d45b1d94d1790bc16168135453590f","translation":"AI-assisted, block-aligned; not official","head":[["link",{"rel":"canonical","href":"https://thedankoe.com/letters/how-to-become-the-top-1-percent-in-any-skill/"}]]},"headers":[],"relativePath":"letters/how-to-become-the-top-1-percent-in-any-skill.md","filePath":"letters/how-to-become-the-top-1-percent-in-any-skill.md"}'),c={name:"letters/how-to-become-the-top-1-percent-in-any-skill.md"};function h(m,e,d,b,u,_){const a=o("ArticleMeta");return p(),l("div",null,[e[0]||(e[0]=t("h1",{id:"如何-在任何技能上成为前1",tabindex:"-1"},[n("如何：在任何技能上成为前1% "),t("a",{class:"header-anchor",href:"#如何-在任何技能上成为前1","aria-label":'Permalink to "如何：在任何技能上成为前1%"'},"​")],-1)),s(a),e[1]||(e[1]=i('<p>每个人都想成就一番伟业，但没有人愿意连续数年专注于打磨自己的手艺。</p><p>（剧情反转：其实每个人都想专注于自己的手艺，但没有人愿意做内在的功课，摆脱他们错误的信念，追求非传统的道路，并看穿你的朋友、家人和文化投射在你身上的东西）</p><p>恐惧挡了你的路。放下吧。</p><h2 id="唯一值得走的道路" tabindex="-1"><strong>唯一值得走的道路</strong> <a class="header-anchor" href="#唯一值得走的道路" aria-label="Permalink to &quot;**唯一值得走的道路**&quot;">​</a></h2><p>在你的一生中，你一直被规训着走别人希望你走的路。你周围的每个人都在把他们的恐惧、不安全感和糟糕的选择投射到你身上。不管他们有没有意识到，他们都不想看到你过得比他们好。所以，他们放出那些话语和反应，希望能把你留在和他们一样的水平。</p><p>如果你没注意到的话，大多数人都不快乐。我的意思是，他们怎么可能快乐呢？过多的屏幕时间和廉价娱乐烧坏了多巴胺受体。糟糕的营养、缺乏运动以及没有目标感导致基线能量极低。种种认知让你对直勾勾盯着你的无限机遇视而不见。这简直是一场灾难（对于那些任由其保持灾难状态的人来说）。</p><p>事情是这样的，成长是自然而然的。也就是说，当你越来越接近自然、“宇宙”或真实的自我时——当你摆脱那些阻碍你的事物，成长和进步就是唯一的选项。一旦你摧毁了你习得的、基于恐惧的世界观——你就向真实的当下敞开了自己。你的直觉会显现。你的好奇心会显现。你想要发挥天生男性/女性优势的内在驱动力也会显现。去建设、保护、提供、哺育、支持等等。</p><p>个人和职业的发展，是“放下”那些对你无益（且你无法控制）的外部事物时自然产生的副产品。抗拒、与之搏斗并紧抓着这些东西不放，正是将你困在枷锁中的原因。</p><p>这个困境让我想起了詹姆斯·克莱尔（James Clear）发的一条很棒的推文：</p><blockquote><p>我怀疑大多数成年人（75%以上）可以挑选任何一项技能——除了体育——只要连续两年每天专心致志地练习，就能跻身世界前10%。</p><p>但几乎没有人展现出那种程度的专注，所以我们永远无从知晓。</p><p>— 詹姆斯·克莱尔 (@JamesClear) <a href="https://twitter.com/JamesClear/status/1292574538912456707?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2020年8月9日</a></p></blockquote><p>首先，我认为大多数人可以跻身前1%——而不是前10%。（那些把这个“统计数据”过度理论化的人是达不到前1%的，因为他们脑海中的喋喋不休阻止了他们采取行动去放下）。外界有太多高质量的资源，能让你在创纪录的时间内打造自己和你的事业。然而，人们却被我们上面讨论过的短暂分心事物所阻碍。那些外部刺激把你困在了一个熟悉而舒适的泡泡里。</p><p><em>问题是，你该从哪里开始？</em></p><p>我已经让你意识到了这些分心事物——你现在的任务就是每时每刻都留意它们。深呼吸，让它们过去。顺应自然、积极的生活方式流动。这需要练习。终生的练习。假以时日，你的好奇心就会开始把你拉向你命中注定要去的方向。</p><p>当那个时刻到来时（或者如果你想强行推进这个过程），你应该这样做。</p><h2 id="_3-2-1-精通框架" tabindex="-1"><strong>3-2-1 精通框架</strong> <a class="header-anchor" href="#_3-2-1-精通框架" aria-label="Permalink to &quot;**3-2-1 精通框架**&quot;">​</a></h2><p>掌握任何技能或在生活中取得进步的第一步是<em>学习</em>。学习是好奇心之后的一步。学习是在任何特定领域取得成功的第一步。你的父母在青春期教导你，然后你在教育系统中度过12-24_年_，这是有原因的。值得庆幸的是，在线教育已经并将继续发展，提供与你任何想做的事情相关的特定知识。</p><p>顺便说一句：学习可能弊大于利——但这将是另一封通讯要讨论的话题。教育是必要之恶。它只对那些仍然沉睡的人来说是一种恶。保持觉察，并敞开心扉，放下那些对你当前处境无益的已学信息。</p><p>回到我刚才说的话：</p><blockquote><p>看看几个YouTube视频就能比一个读了12年学位的人赚得多，这有点疯狂</p><p>— 丹·柯伊 (Dan Koe) (@thedankoe) <a href="https://twitter.com/thedankoe/status/1447493938605068289?ref_src=twsrc%5Etfw" target="_blank" rel="noreferrer">2021年10月11日</a></p></blockquote><p>对一些人来说，自我教育和追求非传统道路的渴望是自然而然产生的。他们在孩童时期就很叛逆，拒绝听从权威。他们唯一的选择是在网上关注那些自信发言并与自己兴趣契合的人。大多数人都会这样做——但很多人并没有从消费者转变为创作者（creator）的内在压力。</p><p>对于那些哪怕有一丝兴趣想要挣脱摆在你面前的传统道路（别人出于投射的恐惧而期望你走的路）的人来说——这正是为你准备的。那是第一步。如果你还不愿意或没准备好踏上通过内在好奇心追求你毕生事业的道路，那就别再往下读了。</p><p>接下来这个 3-2-1 框架将为“弄清楚我一生想做什么”的困境带来结构化的解决方案。</p><p><a href="https://www.youtube.com/embed/3kSMxMlbktc?feature=oembed" target="_blank" rel="noreferrer">观看原文视频</a></p><h3 id="_3个资源——兴趣沉浸" tabindex="-1"><strong>3个资源——兴趣沉浸</strong> <a class="header-anchor" href="#_3个资源——兴趣沉浸" aria-label="Permalink to &quot;**3个资源——兴趣沉浸**&quot;">​</a></h3><p>让自己接触与兴趣相关的信息，目的是为了建立联系。联系和模式识别才是创造动力的源泉。那就是多巴胺信号提供的那种难以言喻的兴奋感。</p><p>在这一点上，你需要有一个去追求的兴趣。也许是你看到别人在做，你也想做的事情。也许是能给你的生活带来积极改变的事情。也许只是一个听起来很有趣的爱好。挑一个吧。你随时可以重新开始。</p><p>说到这3个资源。你将选择一本书、一个长篇资源和一个短篇资源，开始让自己沉浸在该兴趣中。</p><p>这本书应该是该特定兴趣领域内的畅销书或高分书籍。这会让你从宏观上了解这个兴趣是如何与生活的其他领域产生交集的。它会为你提供值得细细咀嚼的想法，以及需要记录下来的金玉良言。</p><p>长篇资源可以来自播客、博客或YouTube频道。这将为你打开一个充满机会的兔子洞，让你一探究竟。在这里，你必须拥抱你的好奇心。如果你觉得仿佛受到某种神圣的召唤，非要花5个小时看YouTube上的健身视频不可——那就看吧。单单是这一点，就可能成为你终生以热情为燃料赚取收入的开端。</p><p>短篇资源将来自谈论你感兴趣话题的社交媒体账号。你可以搜索“X细分领域（niche）最值得关注的账号”这类合集，或者留意突然跳到你时间线上的Twitter账号列表。</p><p>有趣的事实：正是那些看似烦人的Twitter账号列表之一，把我引入了Twitter上专注于自我提升的圈子。现在我是那个圈子里最大的账号之一。这些事情的运作方式真是有趣。</p><p>请注意，短篇内容有其作用，但很容易让你分心，阻碍你取得进展。你不需要在一天之内看到300多条意见（推文）来告诉你该做什么不该做什么。短篇内容有助于让你保持在正轨上，并带来潜在机会，但应当适度。如果你愿意的话，完全可以不看短篇内容。你的大脑会感谢你的。</p><h3 id="_2个输出渠道——热情测试" tabindex="-1"><strong>2个输出渠道——热情测试</strong> <a class="header-anchor" href="#_2个输出渠道——热情测试" aria-label="Permalink to &quot;**2个输出渠道——热情测试**&quot;">​</a></h3><p>模式识别以及将信息应用于现实世界问题的能力，才是创造热情的源泉。将现实世界与你脑海中的信息“把点连成线”，能提升多巴胺水平。你会<em>感觉</em>到那种兴奋。</p><p>当你通过你的3个资源进行学习时——你必须开始产出，试图理清你所学到的东西。正如<a href="https://www.modernmastery.co/post/learn-these-skills-if-you-want-to-thrive-in-2022" target="_blank" rel="noreferrer">常青技能</a>中所说，写作和说话就是你的输出渠道。在Twitter上写，在你的日记里写，或者在一个新的博客上写，以此来激发更多的模式识别，帮助你消化所学。写一本电子书，为一个应用程序写代码，或者打造一个真实世界的项目。与你可以倾诉的朋友交谈，教给他们你正在学习的东西，让你潜在的热情在你的声音中展现出来。</p><p>你可以更进一步，启动一个与该兴趣相关的项目。一个社交媒体品牌，一家电子商务商店，或者某个具有变现潜力的东西——这就引入了其他常青技能，即营销和销售。这能让你连接更多的点。这就是人们对创业着迷的原因。</p><h3 id="_1个月——连接与反思" tabindex="-1"><strong>1个月——连接与反思</strong> <a class="header-anchor" href="#_1个月——连接与反思" aria-label="Permalink to &quot;**1个月——连接与反思**&quot;">​</a></h3><p>你必须给你的兴趣探索留出时间，让它在你的脑海中酝酿发酵。当大多数人在2周后就放弃时，请坚持这项兴趣1个月。向自己证明，你至少能学到该兴趣中的<em>一些</em>错综复杂的门道。</p><p>经过一个月的读书、消费内容、写作和讲述之后——是时候反思了。这将最终确定你是应该现在放弃还是继续走下去。</p><blockquote><p>要明白：这与闪亮物品综合症（shiny object syndrome）毫无关系。万事万物都是相互联系的。如果你继续追求你的兴趣，你会找到你想要精通的那个领域。你一路上其他的学习只会为这次探索添砖加瓦。我之前的7次“失败的”商业尝试，恰恰在我找到我想追求的事业时帮助我取得了成功。<em>如果我没有（从其他兴趣中获得的）背景知识来将其变为现实，我就不会知道这就是我想追求的东西。</em></p></blockquote><p>写下这些问题，来反思你这1个月的旅程：</p><ul><li>这是我想进一步追求的东西吗？</li><li>对于去深挖更多关于这个的书籍和内容，我感到兴奋吗？</li><li>这项技能或兴趣实用吗？其他人是否在靠它变现？</li><li>我能用它解决什么问题？我能想象自己把它作为毕生事业来追求吗？</li><li>这次探索是否让我意识到了我想去探索的一条新途径？</li></ul><p>我无法告诉你应该选择做什么。那取决于你。这些问题会有所帮助。</p><p>综上，我鼓励你使用这个 3-2-1 的过程。最坏的结果，是你花了一个月的时间去追求积极的进步，并在未知中开辟了探索的新途径。最好的结果，是你找到了你将倾注一生的事业。通往精通、金钱以及更高质量的生活。</p><p>如果你喜欢这篇通讯，请给我回复或在Twitter上分享它。感谢你的阅读。</p><p><em>丹·柯伊</em></p><hr><p><a href="/en/letters/how-to-become-the-top-1-percent-in-any-skill">查看英文存档</a> · <a href="/letters/">返回全部文章</a></p>',48))])}const w=r(c,[["render",h]]);export{f as __pageData,w as default};
